COPY "public"."projects" ("id", "name", "description", "guideline", "created_at", "created_by") FROM stdin;
e321ff7d-3b01-4a85-b815-241a1b9d6110	Culture Connectedness Evaluation - Nigeria - Hausa	A project to evaluate health stories for cultural alignment	<div>\n    <div class="mt-4">\n        <div\n            class="guideline-html-content text-xs font-medium text-slate-500 leading-relaxed prose prose-slate max-w-none">\n            <div class="space-y-4 font-sans text-slate-700">\n\n                <!-- Section 1: Purpose & Scope -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm" open="">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🎯 Purpose &amp; Scope</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-4 leading-relaxed border-t border-slate-100 pt-4">\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Purpose</h4>\n                            <p>Evaluates (A) Cultural alignment and (B) Multimodal health story quality of AI-generated\n                                diabetes lifestyle stories for specific African communities.</p>\n                        </div>\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Scope</h4>\n                            <p>Stories in English (isiXhosa, Hausa, Kikuyu, Luo, Swahili cultures) and Portuguese\n                                (Xichangana culture).</p>\n                            <ul class="list-disc ml-5 space-y-1 mt-2">\n                                <li><strong>Cultural Alignment:</strong> Presence, correctness, plausibility, and\n                                    relevance of cultural signals.</li>\n                                <li><strong>Multimodal Quality:</strong> Text quality (grammar, fluency) and Image\n                                    quality (artifacts, mismatches).</li>\n                            </ul>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Demo</h4>\n                            <p> Download the demo file <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/AnnotationPlatformDemo.pdf" target="_blank">here</a></p>\n                            <p> See the PDF guidelines <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/Annotation%20Guidelines%201.19.2026.pdf" target="_blank">here</a></p>\n                        </div>\n\n\n                    </div>\n                </details>\n\n                <!-- Section 2: Inputs -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>📦 Inputs Provided</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-2 leading-relaxed border-t border-slate-100 pt-4">\n                        <ul class="list-decimal ml-5 space-y-2">\n                            <li><strong>Patient Persona:</strong> Demographics, culture, health condition (Type II\n                                Diabetes).</li>\n                            <li><strong>Health Question:</strong> Specific lifestyle question (diet/exercise).</li>\n                            <li><strong>Generated Health Story (Text):</strong> First-person narrative response.</li>\n                            <li><strong>Generated Image:</strong> Visual content aligning with the story.</li>\n                            <li><strong>Audio:</strong> Context only (do not explicitly evaluate).</li>\n                        </ul>\n                    </div>\n                </details>\n\n                <!-- Section 3: Cultural Markers -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🏷️ Cultural Markers Definition</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-6 leading-relaxed border-t border-slate-100 pt-4">\n                        <p class="italic">A cultural marker signals culturally specific norms, practices, identities,\n                            values, or environments.</p>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">A. Demographic\n                                Proxies</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Description</th>\n                                            <th class="p-2 border-b">Illustrations (Text/Image)</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Language</td>\n                                            <td class="p-2">Appropriate language/dialect</td>\n                                            <td class="p-2">Greetings, signage</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Ethnicity</td>\n                                            <td class="p-2">Implicit/explicit identity</td>\n                                            <td class="p-2">Community practices, settings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Region</td>\n                                            <td class="p-2">Rural vs Urban</td>\n                                            <td class="p-2">Markets, transport, village</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Religion</td>\n                                            <td class="p-2">Faith-based practices</td>\n                                            <td class="p-2">Prayer, religious spaces</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Socio-economic</td>\n                                            <td class="p-2">Access to resources</td>\n                                            <td class="p-2">Public transport, informal trade</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Age/Gender</td>\n                                            <td class="p-2">Roles &amp; Expectations</td>\n                                            <td class="p-2">Caregiving, intergenerational scenes</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Occupation</td>\n                                            <td class="p-2">Work Identity</td>\n                                            <td class="p-2">Tools, uniforms, work environments</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">B. Semantic\n                                Proxies</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Description</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Food &amp; Diet</td>\n                                            <td class="p-2">What/how/when people eat (e.g., Ugali, communal meals)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Physical Activity</td>\n                                            <td class="p-2">Movement patterns (walking, farming)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Kinship</td>\n                                            <td class="p-2">Family structure, extended support</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Community</td>\n                                            <td class="p-2">Collective routines, gatherings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Etiquette</td>\n                                            <td class="p-2">Respect norms, greetings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Values</td>\n                                            <td class="p-2">Collective well-being vs individual</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Emotion/Attitude</td>\n                                            <td class="p-2">Framing of illness, resilience</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n                    </div>\n                </details>\n\n                <!-- Section 4: Annotation Tasks -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>✅ Annotation Tasks</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-4 leading-relaxed border-t border-slate-100 pt-4">\n                        <div class="space-y-4">\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 1: Marker\n                                    Identification</h5>\n                                <p>Identify markers in text/image. Assign category from list. Use "Other" with\n                                    justification if needed.</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 2: Support\n                                    (Yes/No)</h5>\n                                <p>Is it plausible/correct for the persona &amp; culture?</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 3:\n                                    Relevance (Yes/No)</h5>\n                                <p>Does it meaningfully inform the lifestyle advice?</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 4:\n                                    Intangible Markers</h5>\n                                <p>Assess tone, narrative voice, and implied values (e.g., individual vs collective).\n                                </p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 5:\n                                    Alignment Score (0-100)</h5>\n                                <ul class="list-none space-y-1 text-xs">\n                                    <li><span class="font-bold w-12 inline-block">0:</span> No markers</li>\n                                    <li><span class="font-bold w-12 inline-block">1-40:</span> Minimal/Weak</li>\n                                    <li><span class="font-bold w-12 inline-block">41-60:</span> Moderate</li>\n                                    <li><span class="font-bold w-12 inline-block">61-80:</span> Strong</li>\n                                    <li><span class="font-bold w-12 inline-block">81+:</span> Deep, coherent alignment\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </details>\n\n                <!-- Section 5: Quality Issues -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🚩 Quality Issue Reporting</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-6 leading-relaxed border-t border-slate-100 pt-4">\n\n                        <div>\n                            <h4 class="font-bold text-red-500 mb-2 uppercase text-xs tracking-widest">📝 Text Issues\n                                (T1-T7)</h4>\n                            <ul class="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs">\n                                <li class="bg-red-50 p-2 rounded"><strong>T1:</strong> Coherence/Logic (contradictions)\n                                </li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T2:</strong> Instruction Clarity (vague)</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T3:</strong> Persona Inconsistency</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T4:</strong> Tokenism/Stereotype</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T5:</strong> Language/Fluency</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T6:</strong> Safety/Health Harm Risk</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T7:</strong> Other</li>\n                            </ul>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-red-500 mb-2 uppercase text-xs tracking-widest">🖼️ Image Issues\n                                (I1-I7)</h4>\n                            <ul class="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs">\n                                <li class="bg-rose-50 p-2 rounded"><strong>I1:</strong> Missing/Unviewable</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I2:</strong> Low Visual Quality (blurry,\n                                    artifacts)</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I3:</strong> Content Mismatch (wrong setting)\n                                </li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I4:</strong> Cultural Inauthenticity\n                                    ("Western default")</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I5:</strong> Safety/Medical Misleading</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I6:</strong> Sensitive/Offensive</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I7:</strong> Other</li>\n                            </ul>\n                        </div>\n\n                    </div>\n                </details>\n\n            </div>\n        </div>\n    </div>\n    <style>\n        .guideline-html-content h1 {\n            font-size: 1.1rem;\n            font-weight: 800;\n            margin-bottom: 0.5rem;\n        }\n\n        .guideline-html-content h2 {\n            font-size: 1rem;\n            font-weight: 700;\n            margin-bottom: 0.4rem;\n            margin-top: 1rem;\n        }\n\n        .guideline-html-content h3 {\n            font-size: 0.9rem;\n            font-weight: 600;\n            margin-bottom: 0.3rem;\n            margin-top: 0.8rem;\n        }\n\n        .guideline-html-content p {\n            margin-bottom: 0.75rem;\n        }\n\n        .guideline-html-content ul,\n        .guideline-html-content ol {\n            margin-bottom: 0.75rem;\n            padding-left: 1.25rem;\n        }\n\n        .guideline-html-content li {\n            margin-bottom: 0.2rem;\n        }\n\n        .guideline-html-content strong {\n            font-weight: 700;\n            color: #1e293b;\n        }\n    </style>\n</div>	2026-01-14 13:35:04.275+00	f9ea20bc-243a-4f24-b8d8-567890a7d9d4
e321ff7d-3b01-4a85-b815-241a1b9d6120	Culture Connectedness Evaluation - South Africa - IsiXhosa	A project to evaluate health stories for cultural alignment	<h4>🎯&nbsp;Purpose&nbsp;&amp;&nbsp;Scope&nbsp;▼Purpose</h4><p>Evaluates&nbsp;(A)&nbsp;Cultural&nbsp;alignment&nbsp;and&nbsp;(B)&nbsp;Multimodal&nbsp;health&nbsp;story&nbsp;quality&nbsp;of&nbsp;AI-generated&nbsp;diabetes&nbsp;lifestyle&nbsp;stories&nbsp;for&nbsp;specific&nbsp;African&nbsp;communities.</p><h4>Scope</h4><p>Stories&nbsp;in&nbsp;English&nbsp;(isiXhosa,&nbsp;Hausa,&nbsp;Kikuyu,&nbsp;Luo,&nbsp;Swahili&nbsp;cultures)&nbsp;and&nbsp;Portuguese&nbsp;(Xichangana&nbsp;culture).</p><ul><li><strong>Cultural&nbsp;Alignment:</strong>&nbsp;Presence,&nbsp;correctness,&nbsp;plausibility,&nbsp;and&nbsp;relevance&nbsp;of&nbsp;cultural&nbsp;signals.</li><li><strong>Multimodal&nbsp;Quality:</strong>&nbsp;Text&nbsp;quality&nbsp;(grammar,&nbsp;fluency)&nbsp;and&nbsp;Image&nbsp;quality&nbsp;(artifacts,&nbsp;mismatches).</li></ul><h4>Demo</h4><p>Download&nbsp;the&nbsp;demo&nbsp;file&nbsp;<a href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/AnnotationPlatformDemo.pdf" rel="noopener noreferrer" target="_blank" style="color: blue;">here</a></p><p>See&nbsp;the&nbsp;PDF&nbsp;guidelines&nbsp;<a href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/Annotation%20Guidelines%201.19.2026.pdf" rel="noopener noreferrer" target="_blank" style="color: blue;">here</a></p><ul><li>&nbsp;&nbsp;📦&nbsp;Inputs&nbsp;Provided&nbsp;▼<strong>Patient&nbsp;Persona:</strong>&nbsp;Demographics,&nbsp;culture,&nbsp;health&nbsp;condition&nbsp;(Type&nbsp;II&nbsp;Diabetes).</li><li><strong>Health&nbsp;Question:</strong>&nbsp;Specific&nbsp;lifestyle&nbsp;question&nbsp;(diet/exercise).</li><li><strong>Generated&nbsp;Health&nbsp;Story&nbsp;(Text):</strong>&nbsp;First-person&nbsp;narrative&nbsp;response.</li><li><strong>Generated&nbsp;Image:</strong>&nbsp;Visual&nbsp;content&nbsp;aligning&nbsp;with&nbsp;the&nbsp;story.</li><li><strong>Audio:</strong>&nbsp;Context&nbsp;only&nbsp;(do&nbsp;not&nbsp;explicitly&nbsp;evaluate).</li></ul><p>&nbsp;&nbsp;🏷️&nbsp;Cultural&nbsp;Markers&nbsp;Definition&nbsp;▼A&nbsp;cultural&nbsp;marker&nbsp;signals&nbsp;culturally&nbsp;specific&nbsp;norms,&nbsp;practices,&nbsp;identities,&nbsp;values,&nbsp;or&nbsp;environments.</p><h4>A.&nbsp;Demographic&nbsp;Proxies</h4><table style="border: 1px solid #000;"><tbody><tr><td data-row="1">Proxy&nbsp;Description&nbsp;Illustrations&nbsp;(Text/Image)</td></tr><tr><td data-row="2">&nbsp;Language</td><td data-row="2">Appropriate&nbsp;language/dialect</td><td data-row="2">Greetings,&nbsp;signage</td></tr><tr><td data-row="3">Ethnicity</td><td data-row="3">Implicit/explicit&nbsp;identity</td><td data-row="3">Community&nbsp;practices,&nbsp;settings</td></tr><tr><td data-row="4">Region</td><td data-row="4">Rural&nbsp;vs&nbsp;Urban</td><td data-row="4">Markets,&nbsp;transport,&nbsp;village</td></tr><tr><td data-row="5">Religion</td><td data-row="5">Faith-based&nbsp;practices</td><td data-row="5">Prayer,&nbsp;religious&nbsp;spaces</td></tr><tr><td data-row="6">Socio-economic</td><td data-row="6">Access&nbsp;to&nbsp;resources</td><td data-row="6">Public&nbsp;transport,&nbsp;informal&nbsp;trade</td></tr><tr><td data-row="7">Age/Gender</td><td data-row="7">Roles&nbsp;&amp;&nbsp;Expectations</td><td data-row="7">Caregiving,&nbsp;intergenerational&nbsp;scenes</td></tr><tr><td data-row="8">Occupation</td><td data-row="8">Work&nbsp;Identity</td><td data-row="8">Tools,&nbsp;uniforms,&nbsp;work&nbsp;environments</td></tr></tbody></table><h4>B.&nbsp;Semantic&nbsp;Proxies</h4><table style="border: 1px solid #000;"><tbody><tr><td data-row="1">Proxy&nbsp;Description</td></tr><tr><td data-row="2">&nbsp;Food&nbsp;&amp;&nbsp;Diet</td><td data-row="2">What/how/when&nbsp;people&nbsp;eat&nbsp;(e.g.,&nbsp;Ugali,&nbsp;communal&nbsp;meals)</td></tr><tr><td data-row="3">Physical&nbsp;Activity</td><td data-row="3">Movement&nbsp;patterns&nbsp;(walking,&nbsp;farming)</td></tr><tr><td data-row="4">Kinship</td><td data-row="4">Family&nbsp;structure,&nbsp;extended&nbsp;support</td></tr><tr><td data-row="5">Community</td><td data-row="5">Collective&nbsp;routines,&nbsp;gatherings</td></tr><tr><td data-row="6">Etiquette</td><td data-row="6">Respect&nbsp;norms,&nbsp;greetings</td></tr><tr><td data-row="7">Values</td><td data-row="7">Collective&nbsp;well-being&nbsp;vs&nbsp;individual</td></tr><tr><td data-row="8">Emotion/Attitude</td><td data-row="8">Framing&nbsp;of&nbsp;illness,&nbsp;resilience</td></tr></tbody></table><h5>&nbsp;&nbsp;✅&nbsp;Annotation&nbsp;Tasks&nbsp;▼Step&nbsp;1:&nbsp;Marker&nbsp;Identification</h5><p>Identify&nbsp;markers&nbsp;in&nbsp;text/image.&nbsp;Assign&nbsp;category&nbsp;from&nbsp;list.&nbsp;Use&nbsp;&quot;Other&quot;&nbsp;with&nbsp;justification&nbsp;if&nbsp;needed.</p><h5>Step&nbsp;2:&nbsp;Support&nbsp;(Yes/No)</h5><p>Is&nbsp;it&nbsp;plausible/correct&nbsp;for&nbsp;the&nbsp;persona&nbsp;&amp;&nbsp;culture?</p><h5>Step&nbsp;3:&nbsp;Relevance&nbsp;(Yes/No)</h5><p>Does&nbsp;it&nbsp;meaningfully&nbsp;inform&nbsp;the&nbsp;lifestyle&nbsp;advice?</p><h5>Step&nbsp;4:&nbsp;Intangible&nbsp;Markers</h5><p>Assess&nbsp;tone,&nbsp;narrative&nbsp;voice,&nbsp;and&nbsp;implied&nbsp;values&nbsp;(e.g.,&nbsp;individual&nbsp;vs&nbsp;collective).</p><h5>Step&nbsp;5:&nbsp;Alignment&nbsp;Score&nbsp;(0-100)</h5><ul><li>0:&nbsp;No&nbsp;markers</li><li>1-40:&nbsp;Minimal/Weak</li><li>41-60:&nbsp;Moderate</li><li>61-80:&nbsp;Strong</li><li>81+:&nbsp;Deep,&nbsp;coherent&nbsp;alignment</li></ul><h4>&nbsp;&nbsp;🚩&nbsp;Quality&nbsp;Issue&nbsp;Reporting&nbsp;▼📝&nbsp;Text&nbsp;Issues&nbsp;(T1-T7)</h4><ul><li><strong>T1:</strong>&nbsp;Coherence/Logic&nbsp;(contradictions)</li><li><strong>T2:</strong>&nbsp;Instruction&nbsp;Clarity&nbsp;(vague)</li><li><strong>T3:</strong>&nbsp;Persona&nbsp;Inconsistency</li><li><strong>T4:</strong>&nbsp;Tokenism/Stereotype</li><li><strong>T5:</strong>&nbsp;Language/Fluency</li><li><strong>T6:</strong>&nbsp;Safety/Health&nbsp;Harm&nbsp;Risk</li><li><strong>T7:</strong>&nbsp;Other</li></ul><h4>🖼️&nbsp;Image&nbsp;Issues&nbsp;(I1-I7)</h4><ul><li><strong>I1:</strong>&nbsp;Missing/Unviewable</li><li><strong>I2:</strong>&nbsp;Low&nbsp;Visual&nbsp;Quality&nbsp;(blurry,&nbsp;artifacts)</li><li><strong>I3:</strong>&nbsp;Content&nbsp;Mismatch&nbsp;(wrong&nbsp;setting)</li><li><strong>I4:</strong>&nbsp;Cultural&nbsp;Inauthenticity&nbsp;(&quot;Western&nbsp;default&quot;)</li><li><strong>I5:</strong>&nbsp;Safety/Medical&nbsp;Misleading</li><li><strong>I6:</strong>&nbsp;Sensitive/Offensive</li><li><strong>I7:</strong>&nbsp;Other</li></ul>	2026-01-14 13:35:04.275+00	f9ea20bc-243a-4f24-b8d8-567890a7d9d4
e321ff7d-3b01-4a85-b815-241a1b9d6224	Culture Connectedness Evaluation - Kenya - Luo	A project to evaluate health stories for cultural alignment	<div>\n    <div class="mt-4">\n        <div\n            class="guideline-html-content text-xs font-medium text-slate-500 leading-relaxed prose prose-slate max-w-none">\n            <div class="space-y-4 font-sans text-slate-700">\n\n                <!-- Section 1: Purpose & Scope -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm" open="">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🎯 Purpose &amp; Scope</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-4 leading-relaxed border-t border-slate-100 pt-4">\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Purpose</h4>\n                            <p>Evaluates (A) Cultural alignment and (B) Multimodal health story quality of AI-generated\n                                diabetes lifestyle stories for specific African communities.</p>\n                        </div>\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Scope</h4>\n                            <p>Stories in English (isiXhosa, Hausa, Kikuyu, Luo, Swahili cultures) and Portuguese\n                                (Xichangana culture).</p>\n                            <ul class="list-disc ml-5 space-y-1 mt-2">\n                                <li><strong>Cultural Alignment:</strong> Presence, correctness, plausibility, and\n                                    relevance of cultural signals.</li>\n                                <li><strong>Multimodal Quality:</strong> Text quality (grammar, fluency) and Image\n                                    quality (artifacts, mismatches).</li>\n                            </ul>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Demo</h4>\n                            <p> Download the demo file <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/AnnotationPlatformDemo.pdf" target="_blank">here</a></p>\n                            <p> See the PDF guidelines <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/Annotation%20Guidelines%201.19.2026.pdf" target="_blank">here</a></p>\n                        </div>\n\n\n                    </div>\n                </details>\n\n                <!-- Section 2: Inputs -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>📦 Inputs Provided</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-2 leading-relaxed border-t border-slate-100 pt-4">\n                        <ul class="list-decimal ml-5 space-y-2">\n                            <li><strong>Patient Persona:</strong> Demographics, culture, health condition (Type II\n                                Diabetes).</li>\n                            <li><strong>Health Question:</strong> Specific lifestyle question (diet/exercise).</li>\n                            <li><strong>Generated Health Story (Text):</strong> First-person narrative response.</li>\n                            <li><strong>Generated Image:</strong> Visual content aligning with the story.</li>\n                            <li><strong>Audio:</strong> Context only (do not explicitly evaluate).</li>\n                        </ul>\n                    </div>\n                </details>\n\n                <!-- Section 3: Cultural Markers -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🏷️ Cultural Markers Definition</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-6 leading-relaxed border-t border-slate-100 pt-4">\n                        <p class="italic">A cultural marker signals culturally specific norms, practices, identities,\n                            values, or environments.</p>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">A. Demographic\n                                Proxies</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Description</th>\n                                            <th class="p-2 border-b">Illustrations (Text/Image)</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Language</td>\n                                            <td class="p-2">Appropriate language/dialect</td>\n                                            <td class="p-2">Greetings, signage</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Ethnicity</td>\n                                            <td class="p-2">Implicit/explicit identity</td>\n                                            <td class="p-2">Community practices, settings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Region</td>\n                                            <td class="p-2">Rural vs Urban</td>\n                                            <td class="p-2">Markets, transport, village</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Religion</td>\n                                            <td class="p-2">Faith-based practices</td>\n                                            <td class="p-2">Prayer, religious spaces</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Socio-economic</td>\n                                            <td class="p-2">Access to resources</td>\n                                            <td class="p-2">Public transport, informal trade</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Age/Gender</td>\n                                            <td class="p-2">Roles &amp; Expectations</td>\n                                            <td class="p-2">Caregiving, intergenerational scenes</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Occupation</td>\n                                            <td class="p-2">Work Identity</td>\n                                            <td class="p-2">Tools, uniforms, work environments</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">B. Semantic\n                                Proxies</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Description</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Food &amp; Diet</td>\n                                            <td class="p-2">What/how/when people eat (e.g., Ugali, communal meals)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Physical Activity</td>\n                                            <td class="p-2">Movement patterns (walking, farming)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Kinship</td>\n                                            <td class="p-2">Family structure, extended support</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Community</td>\n                                            <td class="p-2">Collective routines, gatherings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Etiquette</td>\n                                            <td class="p-2">Respect norms, greetings</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Values</td>\n                                            <td class="p-2">Collective well-being vs individual</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Emotion/Attitude</td>\n                                            <td class="p-2">Framing of illness, resilience</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n                    </div>\n                </details>\n\n                <!-- Section 4: Annotation Tasks -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>✅ Annotation Tasks</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-4 leading-relaxed border-t border-slate-100 pt-4">\n                        <div class="space-y-4">\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 1: Marker\n                                    Identification</h5>\n                                <p>Identify markers in text/image. Assign category from list. Use "Other" with\n                                    justification if needed.</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 2: Support\n                                    (Yes/No)</h5>\n                                <p>Is it plausible/correct for the persona &amp; culture?</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 3:\n                                    Relevance (Yes/No)</h5>\n                                <p>Does it meaningfully inform the lifestyle advice?</p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 4:\n                                    Intangible Markers</h5>\n                                <p>Assess tone, narrative voice, and implied values (e.g., individual vs collective).\n                                </p>\n                            </div>\n                            <div class="bg-slate-50 p-3 rounded-lg">\n                                <h5 class="font-bold text-slate-900 border-b border-slate-200 pb-1 mb-2">Step 5:\n                                    Alignment Score (0-100)</h5>\n                                <ul class="list-none space-y-1 text-xs">\n                                    <li><span class="font-bold w-12 inline-block">0:</span> No markers</li>\n                                    <li><span class="font-bold w-12 inline-block">1-40:</span> Minimal/Weak</li>\n                                    <li><span class="font-bold w-12 inline-block">41-60:</span> Moderate</li>\n                                    <li><span class="font-bold w-12 inline-block">61-80:</span> Strong</li>\n                                    <li><span class="font-bold w-12 inline-block">81+:</span> Deep, coherent alignment\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </details>\n\n                <!-- Section 5: Quality Issues -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🚩 Quality Issue Reporting</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-6 leading-relaxed border-t border-slate-100 pt-4">\n\n                        <div>\n                            <h4 class="font-bold text-red-500 mb-2 uppercase text-xs tracking-widest">📝 Text Issues\n                                (T1-T7)</h4>\n                            <ul class="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs">\n                                <li class="bg-red-50 p-2 rounded"><strong>T1:</strong> Coherence/Logic (contradictions)\n                                </li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T2:</strong> Instruction Clarity (vague)</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T3:</strong> Persona Inconsistency</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T4:</strong> Tokenism/Stereotype</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T5:</strong> Language/Fluency</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T6:</strong> Safety/Health Harm Risk</li>\n                                <li class="bg-red-50 p-2 rounded"><strong>T7:</strong> Other</li>\n                            </ul>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-red-500 mb-2 uppercase text-xs tracking-widest">🖼️ Image Issues\n                                (I1-I7)</h4>\n                            <ul class="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs">\n                                <li class="bg-rose-50 p-2 rounded"><strong>I1:</strong> Missing/Unviewable</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I2:</strong> Low Visual Quality (blurry,\n                                    artifacts)</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I3:</strong> Content Mismatch (wrong setting)\n                                </li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I4:</strong> Cultural Inauthenticity\n                                    ("Western default")</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I5:</strong> Safety/Medical Misleading</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I6:</strong> Sensitive/Offensive</li>\n                                <li class="bg-rose-50 p-2 rounded"><strong>I7:</strong> Other</li>\n                            </ul>\n                        </div>\n\n                    </div>\n                </details>\n\n            </div>\n        </div>\n    </div>\n    <style>\n        .guideline-html-content h1 {\n            font-size: 1.1rem;\n            font-weight: 800;\n            margin-bottom: 0.5rem;\n        }\n\n        .guideline-html-content h2 {\n            font-size: 1rem;\n            font-weight: 700;\n            margin-bottom: 0.4rem;\n            margin-top: 1rem;\n        }\n\n        .guideline-html-content h3 {\n            font-size: 0.9rem;\n            font-weight: 600;\n            margin-bottom: 0.3rem;\n            margin-top: 0.8rem;\n        }\n\n        .guideline-html-content p {\n            margin-bottom: 0.75rem;\n        }\n\n        .guideline-html-content ul,\n        .guideline-html-content ol {\n            margin-bottom: 0.75rem;\n            padding-left: 1.25rem;\n        }\n\n        .guideline-html-content li {\n            margin-bottom: 0.2rem;\n        }\n\n        .guideline-html-content strong {\n            font-weight: 700;\n            color: #1e293b;\n        }\n    </style>\n</div>	2026-01-14 13:35:04.275+00	f9ea20bc-243a-4f24-b8d8-567890a7d9d4
e321ff7d-3b01-4a85-b815-241a1b9d6333	Culture Connectedness Evaluation - Mozambique - Xichangana	A project to evaluate health stories for cultural alignment	<div>\n    <div class="mt-4">\n        <div\n            class="guideline-html-content text-xs font-medium text-slate-500 leading-relaxed prose prose-slate max-w-none">\n            <div class="space-y-4 font-sans text-slate-700">\n\n                <!-- Section 1: Purpose & Scope -->\n                <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm" open="">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🎯 Objetivo e Âmbito</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-4 leading-relaxed border-t border-slate-100 pt-4">\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Objetivo</h4>\n                            <p>Avalia (A) o alinhamento cultural e (B) a qualidade multimodal de histórias de estilo de\n                                vida relacionadas com diabetes, geradas por IA, para comunidades africanas\n                                específicas.</p>\n                        </div>\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Âmbito</h4>\n                            <p>Histórias em inglês (culturas isiXhosa, Hausa, Kikuyu, Luo, Swahili) e em português\n                                (cultura Xichangana).</p>\n                            <ul class="list-disc ml-5 space-y-1 mt-2">\n                                <li><strong>Alinhamento Cultural:</strong> Presença, correção, plausibilidade e\n                                    relevância de sinais culturais.</li>\n                                <li><strong>Qualidade Multimodal:</strong> Qualidade do texto (gramática, fluência) e da\n                                    imagem (artefactos, inconsistências).</li>\n                            </ul>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-slate-900 mb-1">Demonstração</h4>\n                            <p> Faça o download do ficheiro de demonstração <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/AnnotationPlatformDemo-pt.pdf" target="_blank">aqui</a></p>\n                            <p> Consulte as diretrizes em PDF <a style="color: blue" href="https://prxquaevkggpwryikieg.supabase.co/storage/v1/object/public/pdf/Annotation-Guidelines-pt.pdf" target="_blank">aqui</a></p>\n                        </div>\n                    </div>\n                </details>\n\n                <!-- Section 2: Inputs -->\n                <!-- <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>📦 Entradas Fornecidas</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-2 leading-relaxed border-t border-slate-100 pt-4">\n                        <ul class="list-decimal ml-5 space-y-2">\n                            <li><strong>Persona do Paciente:</strong> Dados demográficos, cultura, condição de saúde\n                                (Diabetes Tipo II).</li>\n                            <li><strong>Pergunta de Saúde:</strong> Pergunta específica sobre estilo de vida\n                                (dieta/exercício).</li>\n                            <li><strong>História de Saúde Gerada (Texto):</strong> Resposta narrativa na primeira\n                                pessoa.</li>\n                            <li><strong>Imagem Gerada:</strong> Conteúdo visual alinhado com a história.</li>\n                            <li><strong>Áudio:</strong> Apenas para contexto (não avaliar explicitamente).</li>\n                        </ul>\n                    </div>\n                </details> -->\n\n                <!-- Section 3: Cultural Markers -->\n                <!-- <details class="group bg-white p-4 rounded-xl border border-slate-200 shadow-sm">\n                    <summary\n                        class="font-black text-lg cursor-pointer list-none flex justify-between items-center text-slate-800 outline-none">\n                        <span>🏷️ Definição de Marcadores Culturais</span>\n                        <span class="transition-transform duration-300 group-open:rotate-180 text-slate-400">▼</span>\n                    </summary>\n                    <div class="mt-4 text-sm space-y-6 leading-relaxed border-t border-slate-100 pt-4">\n                        <p class="italic">Um marcador cultural indica normas, práticas, identidades, valores ou\n                            ambientes culturalmente específicos.</p>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">A. Proxies\n                                Demográficos</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Descrição</th>\n                                            <th class="p-2 border-b">Exemplos (Texto/Imagem)</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Língua</td>\n                                            <td class="p-2">Língua/dialeto apropriado</td>\n                                            <td class="p-2">Saudações, sinalização</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Etnia</td>\n                                            <td class="p-2">Identidade implícita/explícita</td>\n                                            <td class="p-2">Práticas comunitárias, contextos</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Região</td>\n                                            <td class="p-2">Rural vs. Urbana</td>\n                                            <td class="p-2">Mercados, transportes, aldeia</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Religião</td>\n                                            <td class="p-2">Práticas baseadas na fé</td>\n                                            <td class="p-2">Oração, espaços religiosos</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Socioeconómico</td>\n                                            <td class="p-2">Acesso a recursos</td>\n                                            <td class="p-2">Transporte público, comércio informal</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Idade/Género</td>\n                                            <td class="p-2">Papéis e expectativas</td>\n                                            <td class="p-2">Cuidado familiar, cenas intergeracionais</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Ocupação</td>\n                                            <td class="p-2">Identidade profissional</td>\n                                            <td class="p-2">Ferramentas, uniformes, ambientes de trabalho</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n\n                        <div>\n                            <h4 class="font-bold text-indigo-600 mb-2 uppercase text-xs tracking-widest">B. Proxies\n                                Semânticos</h4>\n                            <div class="overflow-x-auto border rounded-lg">\n                                <table class="w-full text-left text-xs">\n                                    <thead class="bg-slate-50 font-bold text-slate-500 uppercase">\n                                        <tr>\n                                            <th class="p-2 border-b">Proxy</th>\n                                            <th class="p-2 border-b">Descrição</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class="divide-y divide-slate-100">\n                                        <tr>\n                                            <td class="p-2 font-bold">Alimentação e Dieta</td>\n                                            <td class="p-2">O que/como/quando as pessoas comem (ex.: Ugali, refeições\n                                                comunitárias)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Atividade Física</td>\n                                            <td class="p-2">Padrões de movimento (caminhar, agricultura)</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Parentesco</td>\n                                            <td class="p-2">Estrutura familiar, apoio alargado</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Comunidade</td>\n                                            <td class="p-2">Rotinas coletivas, encontros</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Etiqueta</td>\n                                            <td class="p-2">Normas de respeito, saudações</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Valores</td>\n                                            <td class="p-2">Bem-estar coletivo vs. individual</td>\n                                        </tr>\n                                        <tr>\n                                            <td class="p-2 font-bold">Emoção/Atitude</td>\n                                            <td class="p-2">Forma de enquadrar a doença, resiliência</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div